create extension if not exists pgcrypto;
create type public.app_role as enum ('player','moderator','admin','superadmin');
create type public.game_key as enum ('shyst','poker','realms','rituals','degen','mmo');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,player_id text not null unique check(player_id ~ '^[A-Z0-9]{6}$'),username text not null unique check(username ~ '^[a-zA-Z0-9_]{3,20}$'),display_name text not null check(char_length(display_name) between 1 and 32),avatar_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.user_roles(user_id uuid primary key references auth.users(id) on delete cascade,role public.app_role not null default 'player',granted_by uuid references auth.users(id),granted_at timestamptz not null default now());
create table public.games(key public.game_key primary key,display_name text not null,launch_url text,status text not null default 'planned' check(status in ('planned','development','available','maintenance')),created_at timestamptz not null default now());
insert into public.games(key,display_name,status) values('shyst','SHYST','development'),('poker','CRASHOUT POKER','development'),('realms','REALMS','development'),('rituals','RITUALS','development'),('degen','DEGEN','development'),('mmo','MMO','planned');
create table public.game_wallets(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,game_key public.game_key not null,currency_code text not null,balance bigint not null default 0 check(balance>=0),unique(user_id,game_key,currency_code));
create table public.wallet_ledger(id uuid primary key default gen_random_uuid(),wallet_id uuid not null references public.game_wallets(id),delta bigint not null check(delta<>0),reason text not null,idempotency_key text not null unique,created_at timestamptz not null default now());
create table public.friendships(id uuid primary key default gen_random_uuid(),requester uuid not null references auth.users(id) on delete cascade,addressee uuid not null references auth.users(id) on delete cascade,status text not null default 'pending' check(status in ('pending','accepted','blocked')),created_at timestamptz not null default now(),check(requester<>addressee),unique(requester,addressee));
create table public.game_links(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,game_key public.game_key not null references public.games(key),external_player_id text not null,linked_at timestamptz not null default now(),unique(game_key,external_player_id),unique(user_id,game_key));
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,body text not null,read_at timestamptz,created_at timestamptz not null default now());
create table public.audit_log(id bigint generated always as identity primary key,actor uuid references auth.users(id),action text not null,target_type text,target_id text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=auth.uid() and role in ('admin','superadmin')); $$;
alter table public.profiles enable row level security; alter table public.user_roles enable row level security; alter table public.games enable row level security; alter table public.game_wallets enable row level security; alter table public.wallet_ledger enable row level security; alter table public.friendships enable row level security; alter table public.game_links enable row level security; alter table public.notifications enable row level security; alter table public.audit_log enable row level security;
create policy "profiles readable by authenticated" on public.profiles for select to authenticated using(true);
create policy "profile owner updates safe fields" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "roles readable by self or admin" on public.user_roles for select to authenticated using(user_id=auth.uid() or public.is_admin());
create policy "games readable" on public.games for select to anon,authenticated using(true);
create policy "wallets private read" on public.game_wallets for select to authenticated using(user_id=auth.uid() or public.is_admin());
create policy "ledger private read" on public.wallet_ledger for select to authenticated using(exists(select 1 from public.game_wallets w where w.id=wallet_id and (w.user_id=auth.uid() or public.is_admin())));
create policy "friendships participants read" on public.friendships for select to authenticated using(requester=auth.uid() or addressee=auth.uid());
create policy "friendships requester creates" on public.friendships for insert to authenticated with check(requester=auth.uid());
create policy "friendship recipient updates" on public.friendships for update to authenticated using(addressee=auth.uid()) with check(addressee=auth.uid());
create policy "game links private read" on public.game_links for select to authenticated using(user_id=auth.uid() or public.is_admin());
create policy "notifications private read" on public.notifications for select to authenticated using(user_id=auth.uid());
create policy "notifications owner marks read" on public.notifications for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "audit admin read" on public.audit_log for select to authenticated using(public.is_admin());
-- Intentionally no client-side role grants, wallet writes, ledger writes, or audit inserts. Trusted server functions only.
